#[test]
fn test_ids_are_per_page_unit() {
    crate::testport::assert_eq(pu_id(0, pi_decode()), 260, "page 0 decode");
    crate::testport::assert_eq(pu_id(0, pi_render_text()), 257, "page 0 render with text");
    crate::testport::assert_eq(pu_id(41, pi_decode()), 10756, "page 41 decode: 42 * 256 + 4");
    crate::testport::assert_eq(pu_view_id(0, 1), view_base() + 1, "a kin-made view of page 0");
    crate::testport::assert_eq(pu_view_id(2, 5), view_base() + 517, "and of page 2");
    crate::testport::assert_that(view_base() > pu_id(60000, 255), "no request id reaches the views' range");
}
