#[test]
fn test_the_bitmap_set_keeps_what_kin_makes() {
    let s: &crate::port::BitmapSet = &crate::port::BitmapSet::new();
    crate::testport::assert_eq(crate::port::bms_has(s, 5), 0, "empty");
    crate::testport::assert_eq(crate::port::bitmap_w(crate::port::bms_get(s, 5)), 0, "an absent bitmap is 0 x 0");
    crate::testport::assert_eq(crate::port::bitmap_h(crate::port::bms_get(s, 5)), 0, "in both directions");
    let b: &crate::port::Bitmap = crate::port::bms_put(s, view_base(), 4, 3, 1);
    crate::testport::assert_eq(crate::port::bms_has(s, view_base()), 1, "put");
    crate::testport::assert_eq(crate::port::bitmap_w(b), 4, "its width");
    crate::testport::assert_eq(crate::port::bitmap_h(b), 3, "its height");
    crate::testport::assert_eq(crate::port::bitmap_channels(b), 1, "its channels");
    crate::testport::assert_eq(crate::port::bitmap_u8(b, 1, 1, 0), 0, "zeroed");
    crate::port::bitmap_set_u8(b, 1, 1, 0, 200);
    crate::testport::assert_eq(crate::port::bitmap_u8(crate::port::bms_get(s, view_base()), 1, 1, 0), 200, "the set holds the very bitmap kin filled");
    crate::testport::assert_eq(crate::port::bms_has(s, view_base() + 1), 0, "another id is absent");
}
